import numpy as np
from math import exp, sqrt

def pathwise_delta(S0, K, r, sigma, T, n, seed):
    """Pathwise delta of the call: (estimate, standard error) from n draws."""
    z = np.random.default_rng(seed).standard_normal(n)
    st = S0 * np.exp((r - sigma ** 2 / 2) * T + sigma * sqrt(T) * z)
    x = exp(-r * T) * (st > K) * st / S0
    return float(x.mean()), float(x.std(ddof=1) / sqrt(n))

def digital_pathwise(S0, K, r, sigma, T, n, seed):
    """Pathwise delta of the digital: (estimate, standard error)."""
    z = np.random.default_rng(seed).standard_normal(n)
    x = np.zeros(n)  # a step is flat almost everywhere
    return float(x.mean()), float(x.std(ddof=1) / sqrt(n))
